	const handle = currentHandle();
	const node = {
		$type: TSKindId.LiteralValue as const,
		$named: true as const,
		_elements,
		$with: {
			elements: (...args: unknown[]) =>
				rebuilt(node, handle, () =>
					listSlotWith(
						args,
						{ kind: TSKindId.LiteralValueElements as const, optional: true, make: buildLiteralValueElements },
						(value?: Admit<T.LiteralValueElements>) => _buildLiteralValue(value)
					)
				)
		},
		elements: () => hydrateStoredSlot(node, '_elements'),
		length: listView.stored?.length,
		[LIST_ITEMS]: undefined,
		[LIST_READ]: () => listItems(ownerElements(node.elements(), 'items'), undefined),
		...LIST_METHODS,
		[Symbol.iterator]: listIterator,
		[Symbol.isConcatSpreadable]: true,
		[Symbol.unscopables]: Array.prototype[Symbol.unscopables],
		delimiter: listOption(listView.list, 'delimiter', undefined),
		$render: () => renderText(handle, node),
		toString: () => node.$render(),
		toJSON: () => nodeJSON(node, jsonFacts),
		$trivia: {
			leading: (...items: unknown[]) => triviaSide(node, handle, 'leading', items),
			trailing: (...items: unknown[]) => triviaSide(node, handle, 'trailing', items),
			inner: (...items: unknown[]) => triviaInner(node, handle, items)
		},
		$engine: handle && (() => handle.current)
	};
	defineListIndices(node, listView.stored?.length ?? 0);
	return stampBuilt(node) as unknown as T.LiteralValue.Bound;
